mapper.sql:
SELECT sc.id, sc.course_id, c.course_code, c.course_name, sc.student_id, st.student_no, st.name AS student_name, cl.class_name, c.semester_id, se.semester_name, sc.usual_score, sc.exam_score, sc.final_score, sc.update_by, u.real_name AS updater_name FROM score sc JOIN course c ON sc.course_id = c.id JOIN student st ON sc.student_id = st.id LEFT JOIN class_info cl ON st.class_id = cl.id JOIN semester se ON c.semester_id = se.id LEFT JOIN sys_user u ON sc.update_by = u.id
AND c.semester_id = #{semesterId}
AND sc.course_id = #{courseId}
AND sc.student_id = #{studentId}
AND c.teacher_id = #{teacherId}
AND (st.student_no LIKE CONCAT('%', #{keyword}, '%') OR st.name LIKE CONCAT('%', #{keyword}, '%') OR c.course_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY se.start_date DESC, c.course_code, st.student_no

mapper.select:
SELECT IFNULL(ROUND(AVG(sc.final_score), 1), 0) AS average, IFNULL(MAX(sc.final_score), 0) AS max, IFNULL(MIN(sc.final_score), 0) AS min, COUNT(sc.final_score) AS total, SUM(CASE WHEN sc.final_score >= 60 THEN 1 ELSE 0 END) AS pass_count, SUM(CASE WHEN sc.final_score >= 90 THEN 1 ELSE 0 END) AS excellent_count, SUM(CASE WHEN sc.final_score < 60 THEN 1 ELSE 0 END) AS bucket0, SUM(CASE WHEN sc.final_score >= 60 AND sc.final_score < 70 THEN 1 ELSE 0 END) AS bucket1, SUM(CASE WHEN sc.final_score >= 70 AND sc.final_score < 80 THEN 1 ELSE 0 END) AS bucket2, SUM(CASE WHEN sc.final_score >= 80 AND sc.final_score < 90 THEN 1 ELSE 0 END) AS bucket3, SUM(CASE WHEN sc.final_score >= 90 THEN 1 ELSE 0 END) AS bucket4 FROM score sc JOIN course c ON sc.course_id = c.id JOIN course_student cs ON cs.course_id = sc.course_id AND cs.student_id = sc.student_id JOIN student st ON sc.student_id = st.id
AND sc.course_id = #{courseId}
AND st.class_id = #{classId}
AND sc.student_id = #{studentId}
AND c.semester_id = #{semesterId}

SELECT c.credit, sc.final_score FROM score sc JOIN course c ON sc.course_id = c.id JOIN course_student cs ON cs.course_id = sc.course_id AND cs.student_id = sc.student_id WHERE sc.student_id = #{studentId} AND sc.final_score IS NOT NULL
AND c.semester_id = #{semesterId}
ORDER BY c.course_code
